            (tenant, order_id),
        ).fetchone()
        if order is None:
            # 跨租户发起一律按不存在处理，不泄漏对象是否存在
            conn.execute("ROLLBACK")
            return None

        active = conn.execute(
            "SELECT 1 FROM settlements WHERE tenant=? AND order_id=? AND status='active'",
            (tenant, order_id),
        ).fetchone()
        if active is not None:
            conn.execute("ROLLBACK")
            raise AlreadySettled("order already has an active settlement")

        # 未收满：已收金额不等于订单金额
        if order["paid_cents"] != order["amount_cents"]:
            conn.execute("ROLLBACK")
            raise OrderNotFullyPaid("order is not fully paid")

        # 对账核销：核销金额取未被冲正的收款合计，须与订单金额闭合
        live_total = conn.execute(
            "SELECT COALESCE(SUM(p.amount_cents),0) AS s FROM payments p "
            "WHERE p.tenant=? AND p.order_id=? AND NOT EXISTS ("
            "SELECT 1 FROM reversals v WHERE v.tenant=p.tenant AND v.order_id=p.order_id AND v.payment_id=p.payment_id)",
            (tenant, order_id),
        ).fetchone()["s"]
        if live_total != order["amount_cents"] or live_total != order["paid_cents"]:
            conn.execute("ROLLBACK")
            raise SettlementAmountsNotClosed("settlement amounts do not close")

        settlement_id = uuid.uuid4().hex
        try:
            conn.execute(
                "INSERT INTO settlements(tenant, settlement_id, order_id, settlement_key, "
                "amount_cents, currency, status) VALUES(?,?,?,?,?,?,'active')",
                (tenant, settlement_id, order_id, settlement_key, order["amount_cents"], order["currency"]),
            )
            conn.execute("COMMIT")
        except sqlite3.IntegrityError:
            # 并发兜底：同一订单的未撤销结算单部分唯一索引，或结算标识被并发占用
            conn.execute("ROLLBACK")
            clash = conn.execute(
                "SELECT * FROM settlements WHERE tenant=? AND settlement_key=?",
                (tenant, settlement_key),
            ).fetchone()
            if clash is not None:
                if clash["order_id"] != order_id:
                    raise SettlementConflict("settlement id already used for another order")
                return _settlement_view(clash)
            raise AlreadySettled("order already has an active settlement")
    finally:
        conn.close()

    saved = connect()
    try:
        row = saved.execute(
            "SELECT * FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
    finally:
        saved.close()
    return _settlement_view(row)


def get_settlement(tenant: str, settlement_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT * FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
    finally:
        conn.close()
    return None if row is None else _settlement_view(row)


def revoke(tenant: str, settlement_id: str, revocation_id: str) -> dict:
    """撤销结算单的核销状态；不存在/已撤销/冲突分别抛出可区分异常。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT settlement_id FROM settlement_revocations WHERE tenant=? AND revocation_id=?",
            (tenant, revocation_id),
        ).fetchone()
        if existing is not None:
            # 幂等重放：同一撤销标识只能指向同一结算单
            conn.execute("ROLLBACK")
            if existing["settlement_id"] != settlement_id:
                raise RevocationConflict("revocation id already used for another settlement")
            saved = connect()
            try:
                row = saved.execute(
                    "SELECT * FROM settlements WHERE tenant=? AND settlement_id=?",
                    (tenant, settlement_id),
                ).fetchone()
            finally:
                saved.close()
            return _revocation_view(row, revocation_id)

        settlement = conn.execute(
            "SELECT * FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
        if settlement is None:
            conn.execute("ROLLBACK")
            raise SettlementNotFound("settlement not found")
        if settlement["status"] == REVOKED:
            conn.execute("ROLLBACK")
            raise SettlementAlreadyRevoked("settlement already revoked")

        try:
            conn.execute(
                "INSERT INTO settlement_revocations(tenant, revocation_id, settlement_id, order_id) "
                "VALUES(?,?,?,?)",
                (tenant, revocation_id, settlement_id, settlement["order_id"]),
            )
            conn.execute(
                "UPDATE settlements SET status='revoked', "
                "revoked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE tenant=? AND settlement_id=?",
                (tenant, settlement_id),
            )
            conn.execute("COMMIT")
        except sqlite3.IntegrityError:
            # 并发下撤销标识被占用，整笔回滚后按重放/冲突分类
            conn.execute("ROLLBACK")
            clash = connect()
            try:
                row = clash.execute(
                    "SELECT settlement_id FROM settlement_revocations WHERE tenant=? AND revocation_id=?",
                    (tenant, revocation_id),
                ).fetchone()
            finally:
                clash.close()
            if row is not None and row["settlement_id"] != settlement_id:
                raise RevocationConflict("revocation id already used for another settlement")
            if row is not None:
                saved = connect()
                try:
                    srow = saved.execute(
                        "SELECT * FROM settlements WHERE tenant=? AND settlement_id=?",
                        (tenant, settlement_id),
                    ).fetchone()
                finally:
                    saved.close()
                return _revocation_view(srow, revocation_id)
            raise SettlementAlreadyRevoked("settlement already revoked")
    finally:
        conn.close()

    saved = connect()
    try:
        row = saved.execute(
            "SELECT * FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
    finally:
        saved.close()
    return _revocation_view(row, revocation_id)


def active_for_order(conn: sqlite3.Connection, tenant: str, order_id: str) -> sqlite3.Row | None:
    """供收款/冲正事务在同一连接内判定订单是否存在未撤销结算单。"""
    return conn.execute(
        "SELECT 1 FROM settlements WHERE tenant=? AND order_id=? AND status='active'",
        (tenant, order_id),
    ).fetchone()


def _settlement_view(row: sqlite3.Row) -> dict:
    return {
        "tenant": row["tenant"],
        "settlement_id": row["settlement_id"],
        "order_id": row["order_id"],
        "settlement_key": row["settlement_key"],
        "amount_cents": row["amount_cents"],
        "currency": row["currency"],
        "status": row["status"],
        "created_at": row["created_at"],
        "revoked_at": row["revoked_at"],
    }


def _revocation_view(row: sqlite3.Row, revocation_id: str) -> dict:
    return {**_settlement_view(row), "revocation_id": revocation_id}

